// Lấy parameters từ webhook request
const body = $('Webhook').first().json.body || $('Webhook').first().json;
const expectedCenterCode = (body.center_code || '').trim().toUpperCase();
const expectedCenterName = (body.center_name || '').trim();
const uploadId = (body.upload_id || '').trim();

function normalizeText(val) {
  if (val === null || val === undefined) return '';
  return String(val).trim().replace(/^\uFEFF/, '').normalize('NFC');
}

function parseMoneyPreserveNull(val) {
  if (val === null || val === undefined) return null;
  const s = String(val).trim();
  if (s === '') return null;
  const cleaned = s.replace(/[^0-9.-]+/g, '');
  if (cleaned === '' || cleaned === '-' || cleaned === '.') return null;
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

const REQUIRED_COLUMNS = [
  'Mã tổ chức',
  'Phiếu công tác sửa chữa',
  'Loại hình đem đến sửa',
  'Số điện thoại người đem đến sửa',
  'Loại hình sửa chữa',
  'Phương án giải quyết',
  'Loại linh kiện',
  'Mã linh kiện',
  'Tên linh kiện',
  'Số tiền phải thu',
  'Số tiền thực thu',
  'Thời gian lấy máy'
];

const RAW_ALLOWED_SOLUTIONS = [
  'Thay thế linh kiện và phụ kiện',
  'Thay thế phụ kiện',
  'Clean (disassemble the machine)'
];
const ALLOWED_SOLUTIONS = new Set(RAW_ALLOWED_SOLUTIONS.map(s => normalizeText(s)));

const allItems = $input.all();
const inputRows = allItems.length;

if (inputRows === 0) {
  return [{
    json: {
      success: false,
      error: 'File Excel không có dữ liệu.',
      inputRows: 0
    }
  }];
}

// 1. Dò tìm header linh hoạt theo tên chuẩn hóa NFC
const allKeys = new Set();
const scanLimit = Math.min(inputRows, 50);
for (let i = 0; i < scanLimit; i++) {
  for (const k of Object.keys(allItems[i].json)) {
    allKeys.add(k);
  }
}

const columnMap = {};
for (const reqCol of REQUIRED_COLUMNS) {
  const normReq = normalizeText(reqCol).toLowerCase();
  let found = null;
  for (const k of allKeys) {
    if (normalizeText(k).toLowerCase() === normReq) {
      found = k;
      break;
    }
  }
  if (!found) {
    return [{
      json: {
        success: false,
        error: 'Không tìm thấy cột bắt buộc: ' + reqCol,
        inputRows
      }
    }];
  }
  columnMap[reqCol] = found;
}

const colToChuc = columnMap['Mã tổ chức'];
const colPhieu = columnMap['Phiếu công tác sửa chữa'];
const colLoaiHinh = columnMap['Loại hình đem đến sửa'];
const colPhone = columnMap['Số điện thoại người đem đến sửa'];
const colLoaiSc = columnMap['Loại hình sửa chữa'];
const colPhuongAn = columnMap['Phương án giải quyết'];
const colLoaiLk = columnMap['Loại linh kiện'];
const colMaLk = columnMap['Mã linh kiện'];
const colTenLk = columnMap['Tên linh kiện'];
const colPhaiThu = columnMap['Số tiền phải thu'];
const colThucThu = columnMap['Số tiền thực thu'];
const colTgLay = columnMap['Thời gian lấy máy'];

let colGiaBanLe = null;
const normGiaBanLe = normalizeText('Giá bán lẻ đề nghị').toLowerCase();
for (const k of allKeys) {
  if (normalizeText(k).toLowerCase() === normGiaBanLe) {
    colGiaBanLe = k;
    break;
  }
}

// 2. Validate Mã tổ chức
const detectedCenters = new Set();
for (const it of allItems) {
  const c = normalizeText(it.json[colToChuc]);
  if (c) detectedCenters.add(c);
}

if (detectedCenters.size > 1) {
  return [{
    json: {
      success: false,
      error: 'File Excel chứa nhiều Mã tổ chức khác nhau (' + Array.from(detectedCenters).join(', ') + ').',
      inputRows
    }
  }];
}

const fileCenterCode = Array.from(detectedCenters)[0] || '';
if (expectedCenterCode && fileCenterCode !== expectedCenterCode) {
  return [{
    json: {
      success: false,
      error: 'File không thuộc TTBH đang đăng nhập. File: ' + fileCenterCode + ', Đăng nhập: ' + expectedCenterCode,
      inputRows
    }
  }];
}

const itemsToAppend = [];
let filteredBySolution = 0;
let warningRows = 0;

for (let idx = 0; idx < inputRows; idx++) {
  const row = allItems[idx].json;
  const sourceRowNumber = idx + 2;

    // Parse và validate Thời gian lấy máy
  const rawPickup = row[colTgLay];
  const pickupTime = normalizeText(rawPickup);
  if (!pickupTime) {
    warningRows++;
    continue;
  }
  const dateMatch = pickupTime.match(/^(\d{4}-\d{2}-\d{2})/);
  if (!dateMatch) {
    warningRows++;
    continue;
  }
  const reportDate = dateMatch[1];

  // Kiểm tra Linh kiện (Phương án 1):
  // Cứ dòng nào có phát sinh Mã linh kiện HOẶC Tên linh kiện thì lấy vào báo cáo (bất kể Phương án giải quyết)
  // Nếu cả 2 đều trống thì bỏ qua
  const partCode = normalizeText(row[colMaLk]);
  const partName = normalizeText(row[colTenLk]);
  if (!partCode && !partName) {
    filteredBySolution++;
    continue;
  }

  const solution = normalizeText(row[colPhuongAn]);

  // Phân loại Khách hàng & Phương thức thanh toán
  const bringType = normalizeText(row[colLoaiHinh]);
  const phone = normalizeText(row[colPhone]);
  const repairCategory = normalizeText(row[colLoaiSc]);

  const isDemo = bringType === normalizeText('Máy demo được gửi đi sửa chữa');
  const isChainTgdd = bringType === normalizeText('Kênh chuỗi gửi sửa') && (phone.startsWith('+84 190') || phone.startsWith('+84 109') || phone.endsWith('464') || phone.endsWith('460'));
  const isTgdd = isDemo || isChainTgdd;

  const customer = isTgdd ? 'TGDĐ' : 'KL';
  const paymentMethod = isTgdd ? 'CN' : 'TM';

  // Xác định Đơn giá: Phương án 2 (Ưu tiên Giá bán lẻ đề nghị, fallback sang Số tiền phải thu)
  const retailPrice = colGiaBanLe ? parseMoneyPreserveNull(row[colGiaBanLe]) : null;
  const phaiThuPrice = parseMoneyPreserveNull(row[colPhaiThu]);
  const unitPrice = retailPrice !== null ? retailPrice : phaiThuPrice;
  const actualPrice = parseMoneyPreserveNull(row[colThucThu]);

  let cashRevenue = null;
  let receivable = null;
  if (unitPrice !== null) {
    const effectiveActual = actualPrice !== null ? actualPrice : 0;
    if (customer === 'TGDĐ') {
      cashRevenue = 0;
      receivable = effectiveActual;
    } else {
      cashRevenue = effectiveActual;
      receivable = 0;
    }
  }
  const partType = normalizeText(row[colLoaiLk]);
  let warrantyExport = '';
  let repairExport = '';

  const isBaoHanhPlusSuaChua = repairCategory.includes(normalizeText('Bảo hành + Sửa chữa')) ||
                               repairCategory.includes(normalizeText('Bảo hành + Sửa chữa'));

  if (isBaoHanhPlusSuaChua) {
    if (partType === normalizeText('Sửa chữa')) {
      repairExport = 1;
      warrantyExport = '';
    } else if (partType === normalizeText('Bảo hành') || partType === normalizeText('Bảo hành')) {
      warrantyExport = 1;
      repairExport = '';
    }
  } else {
    if (partType === normalizeText('Sửa chữa')) {
      repairExport = 1;
      warrantyExport = '';
    } else if (partType === normalizeText('Bảo hành') || partType === normalizeText('Bảo hành')) {
      warrantyExport = 1;
      repairExport = '';
    }
  }

  itemsToAppend.push({
    json: {
      'Mã TTBH': fileCenterCode,
      'Tên TTBH': expectedCenterName || fileCenterCode,
      'Ngày báo cáo': reportDate,
      'Thời gian lấy máy': pickupTime,
      'Số phiếu sửa chữa': normalizeText(row[colPhieu]),
      'Mã vật tư linh kiện': normalizeText(row[colMaLk]),
      'Tên vật tư': normalizeText(row[colTenLk]),
      'Đơn giá': unitPrice,
      'Doanh thu tiền mặt': cashRevenue,
      'Công nợ': receivable,
      'Khách hàng': customer,
      'Phương thức thanh toán': paymentMethod,
      'Xuất Bảo Hành': warrantyExport,
      'Xuất Sửa Chữa': repairExport,
      'Loại hình đem đến sửa': bringType,
      'Loại hình sửa chữa': repairCategory,
      'Loại linh kiện': partType,
      'Phương án giải quyết': solution,
      'Upload ID': uploadId,
      'Source Row Number': sourceRowNumber
    }
  });
}

// Hậu kiểm và ghi đè kết quả hoàn chỉnh (Final Pass Safeguard):
// Check lại thêm 1 lần nữa: nếu Khách hàng là TGDĐ VÀ cả Loại hình sửa chữa lẫn Loại linh kiện đều là Bảo hành
// -> Bắt buộc ghi đè Công nợ = 0 (chỉ riêng đối với TGDĐ) trước khi xuất bản hoàn chỉnh.
for (const it of itemsToAppend) {
  const r = it.json;
  const isTgdd = r['Khách hàng'] === 'TGDĐ';
  const isRepairWarranty = normalizeText(r['Loại hình sửa chữa']).toLowerCase() === normalizeText('Bảo hành').toLowerCase();
  const isPartWarranty = normalizeText(r['Loại linh kiện']).toLowerCase() === normalizeText('Bảo hành').toLowerCase();

  if (isTgdd && isRepairWarranty && isPartWarranty) {
    r['Công nợ'] = 0;
  }
}

return itemsToAppend;

return $input.all().map((item, index) => {
  const row = item.json;
  const centerCode = String(row['Mã TTBH'] || '').trim().toUpperCase();
  const ticket = String(row['Số phiếu sửa chữa'] || '').trim();
  const partCode = String(row['Mã vật tư linh kiện'] || '').trim();
  const partName = String(row['Tên vật tư'] || '').trim().toLowerCase();
  const partIdentity = partCode || `name:${partName}`;
  const normalizedRow = {
    ...row,
    'Loại linh kiện': row['Loại linh kiện'] ?? row['Loại linh kiện'] ?? ''
  };
  delete normalizedRow['Loại linh kiện'];

  return {
    json: {
      ...normalizedRow,
      'Khóa cập nhật': JSON.stringify([centerCode, ticket, partIdentity])
    },
    pairedItem: { item: index }
  };
});

