  JSON.stringify({
    success: true,
    center: {
      code: $('Code - Transform Data').first().json['Mã TTBH'],
      name: $('Code - Transform Data').first().json['Tên TTBH']
    },
    inputRows: $('Extract From File').all().length,
    validRows: $('Code - Transform Data').all().length,
    tgddRows: $('Code - Transform Data').all().filter(i => i.json['Khách hàng'] === 'TGDĐ').length,
    klRows: $('Code - Transform Data').all().filter(i => i.json['Khách hàng'] === 'KL').length,
    totalWarrantyExport: $('Code - Transform Data').all().reduce((acc, i) => acc + (i.json['Xuất Bảo Hành'] || 0), 0),
    totalRepairExport: $('Code - Transform Data').all().reduce((acc, i) => acc + (i.json['Xuất Sửa Chữa'] || 0), 0),
    latestReportDate: $('Code - Transform Data').first().json['Ngày báo cáo']
  })
}}
